import type { BankQuestion } from "@/lib/bank";

/** Compound Interest (Quantitative Aptitude): 139 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-ci-1","question":"Compound interest on ₹10,000 at 10% per annum for 2 years is:","options":["₹2,000","₹2,100","₹2,200","₹2,310"],"answer":1,"explanation":"10,000 × 1.21 = 12,100, so CI = ₹2,100.","difficulty":"easy"},
  {"id":"quant-ci-2","question":"The difference between CI and SI on ₹5,000 for 2 years at 10% is:","options":["₹25","₹50","₹100","₹500"],"answer":1,"explanation":"P(R/100)² = 5,000 × 0.01 = ₹50.","difficulty":"moderate"},
  {"id":"quant-ci-3","question":"₹8,000 at 5% compound interest for 2 years amounts to:","options":["₹8,400","₹8,800","₹8,820","₹9,000"],"answer":2,"explanation":"8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820.","difficulty":"hard"},
  {"id":"quant-ci-4","question":"A sum doubles in 5 years at compound interest. In how many years will it become 8 times?","options":["10","15","20","40"],"answer":1,"explanation":"8 = 2³, so it takes 3 × 5 = 15 years.","difficulty":"very-hard"},
  {"id":"quant-ci-5","question":"The compound interest on ₹5,000 at 4% per annum for 2 years, compounded annually, is:","options":["₹408","₹420","₹400","₹416"],"answer":0,"explanation":"Amount = 5,000 × 1.04² = 5,000 × 1.0816 = ₹5,408, so CI = ₹408. ₹400 is the simple interest.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-6","question":"₹8,000 at 10% per annum compounded half-yearly amounts in 1 year to:","options":["₹8,840","₹8,400","₹8,800","₹8,820"],"answer":3,"explanation":"Half-yearly rate 5% for 2 periods: 8,000 × 1.05² = 8,000 × 1.1025 = ₹8,820. ₹8,800 is the annual-compounding figure.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ci-7","question":"The compound interest on a sum for 2 years at 10% per annum is ₹420. The sum is:","options":["₹4,200","₹1,800","₹2,000","₹2,100"],"answer":2,"explanation":"CI for 2 years at 10% = 21% of the sum, so sum = 420/0.21 = ₹2,000.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-8","question":"The compound interest on ₹8,000 for 1½ years at 10% per annum, compounded annually, is:","options":["₹1,320","₹1,200","₹1,261","₹1,240"],"answer":3,"explanation":"Amount = 8,000 × 1.10 × 1.05 = ₹9,240 (half a year's interest for the fractional period), so CI = ₹1,240. ₹1,261 wrongly compounds half-yearly for 3 periods.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-9","question":"The difference between compound interest and simple interest on ₹10,000 for 3 years at 10% per annum is:","options":["₹300","₹331","₹310","₹100"],"answer":2,"explanation":"SI = ₹3,000; CI = 10,000 × (1.331 − 1) = ₹3,310. Difference = ₹310. ₹100 is the 2-year difference.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-10","question":"At what rate of compound interest per annum does ₹1,600 become ₹1,936 in 2 years?","options":["11%","10%","9%","12%"],"answer":1,"explanation":"(1 + r/100)² = 1,936/1,600 = 1.21, so 1 + r/100 = 1.1 and r = 10%.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ci-11","question":"A sum amounts to ₹4,840 in 2 years and to ₹5,324 in 3 years at compound interest. The sum is:","options":["₹4,200","₹4,400","₹3,600","₹4,000"],"answer":3,"explanation":"Ratio of successive amounts = 5,324/4,840 = 1.1, so the rate is 10%. Sum = 4,840/1.21 = ₹4,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-12","question":"₹5,000 is invested at compound interest at 10% for the first year and 20% for the second year. The compound interest earned is:","options":["₹1,550","₹1,500","₹1,600","₹1,650"],"answer":2,"explanation":"Amount = 5,000 × 1.1 × 1.2 = ₹6,600, so CI = ₹1,600. Using an average rate of 15% for both years gives the wrong ₹1,612.5.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-13","question":"The compound interest on ₹16,000 at 10% per annum compounded half-yearly for 1½ years is:","options":["₹2,522","₹2,480","₹2,400","₹2,520"],"answer":0,"explanation":"Three half-years at 5%: 16,000 × 1.05³ = 16,000 × 1.157625 = ₹18,522, so CI = ₹2,522.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-14","question":"The difference between compound interest and simple interest on a sum for 2 years at 8% per annum is ₹32. The sum is:","options":["₹5,000","₹6,250","₹3,200","₹4,000"],"answer":0,"explanation":"For 2 years the difference = P(r/100)² = P × 0.0064 = 32, so P = ₹5,000.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ci-15","question":"The compound interest for the second year on a sum at 10% per annum is ₹1,210. The interest for the third year is:","options":["₹1,331","₹1,300","₹1,320","₹1,100"],"answer":0,"explanation":"Each year's interest is 1.1 times the previous year's: 1,210 × 1.1 = ₹1,331. (The sum is ₹11,000; ₹1,100 is the first-year interest.)","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-16","question":"A sum becomes 1.44 times itself in 2 years at compound interest. In how many years will it become 2.0736 times itself?","options":["5","4","3","6"],"answer":1,"explanation":"1.44 = 1.2², so the rate is 20%. 1.2⁴ = 2.0736, so 4 years.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-17","question":"A loan of ₹2,100 at 10% per annum compound interest is to be repaid in two equal annual instalments. Each instalment is:","options":["₹1,050","₹1,100","₹1,155","₹1,210"],"answer":3,"explanation":"Present value: x/1.1 + x/1.21 = 2,100. Multiply by 1.21: 1.1x + x = 2,541, so x = ₹1,210. Check: 1,100 + 1,000 = 2,100.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ci-18","question":"The difference between compound interest and simple interest on a sum for 3 years at 10% per annum is ₹62. The sum is:","options":["₹2,100","₹2,000","₹1,800","₹6,200"],"answer":1,"explanation":"For 3 years the difference = P[(1.1)³ − 1 − 0.3] = 0.031P = 62, so P = ₹2,000.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-19","question":"₹8,000 is invested at 5% per annum compound interest. The interest for the third year alone is:","options":["₹420","₹441","₹400","₹462"],"answer":1,"explanation":"Amount at the start of year 3 = 8,000 × 1.05² = ₹8,820; third-year interest = 5% of 8,820 = ₹441.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-20","question":"The compound interest on ₹1,00,000 at 12% per annum compounded quarterly for 6 months is:","options":["₹6,000","₹6,180","₹6,120","₹6,090"],"answer":3,"explanation":"Quarterly rate 3% for 2 quarters: 1,00,000 × 1.03² = 1,06,090, so CI = ₹6,090. ₹6,000 is the simple interest.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-ci-21","question":"How many of the following statements are correct?\n1. For the first year, compound interest equals simple interest at the same rate.\n2. The difference between CI and SI for 2 years is P(r/100)².\n3. 10% per annum compounded half-yearly is equivalent to 10.5% per annum compounded annually.\n4. At compound interest, a sum that doubles in 3 years becomes 8 times in 9 years.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1, 2 and 4 are true (2³ = 8). 3 is false: 1.05² = 1.1025, an effective 10.25%. Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ci-22","question":"The simple interest on a sum at 5% per annum for 2 years is ₹1,000. The compound interest on the same sum at the same rate for 2 years is:","options":["₹1,050","₹1,025","₹1,100","₹1,000"],"answer":1,"explanation":"Sum = 1,000/0.10 = ₹10,000. CI = 10,000 × (1.05² − 1) = 10,000 × 0.1025 = ₹1,025.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-23","question":"₹20,000 is invested for 2 years at 10% per annum: in the first year interest is compounded annually, in the second year half-yearly. The amount at the end of 2 years is:","options":["₹24,255","₹24,200","₹24,310","₹24,000"],"answer":0,"explanation":"After year 1: 20,000 × 1.1 = ₹22,000. Year 2 at 5% per half-year: 22,000 × 1.05² = 22,000 × 1.1025 = ₹24,255.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-24","question":"On ₹10,000 at 20% per annum for 1 year, the compound interest compounded half-yearly exceeds that compounded annually by:","options":["₹210","₹200","₹100","₹50"],"answer":2,"explanation":"Annual: CI = ₹2,000. Half-yearly at 10% for 2 periods: 10,000 × 0.21 = ₹2,100. Difference = ₹100.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "quant-ci-25", "question": "What amount will ₹4,000 become in 2 years at 5% per annum compound interest, compounded annually?", "options": ["₹4,400", "₹4,410", "₹4,420", "₹4,200"], "answer": 1, "explanation": "A = 4,000 × (1.05)² = 4,000 × 1.1025 = ₹4,410. ₹4,400 is the simple-interest amount.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-ci-26", "question": "What is the compound interest on ₹12,500 at 8% per annum for 2 years, compounded annually?", "options": ["₹2,080", "₹2,000", "₹2,160", "₹1,080"], "answer": 0, "explanation": "A = 12,500 × (1.08)² = 12,500 × 1.1664 = 14,580. CI = 14,580 − 12,500 = ₹2,080. ₹2,000 is simple interest.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-ci-27", "question": "A sum amounts to ₹13,310 in 3 years at 10% per annum compound interest. What is the sum?", "options": ["₹10,238", "₹9,317", "₹11,000", "₹10,000"], "answer": 3, "explanation": "P = 13,310 ÷ (1.1)³ = 13,310 ÷ 1.331 = ₹10,000. ₹10,238 divides by 1.3 (simple interest) instead.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-ci-28", "question": "The compound interest on a sum for 2 years at 12.5% per annum is ₹1,530. What is the simple interest on the same sum at the same rate for 2 years?", "options": ["₹1,500", "₹1,360", "₹1,440", "₹1,530"], "answer": 2, "explanation": "12.5% = 1/8, so CI factor = (9/8)² − 1 = 17/64. P = 1,530 × 64/17 = 5,760. SI = 5,760 × 12.5% × 2 = ₹1,440.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ci-29", "question": "A town of 50,000 grows by 10% in the first year, falls by 10% in the second year and grows by 20% in the third year. What is the population after 3 years?", "options": ["60,000", "59,400", "59,000", "60,500"], "answer": 1, "explanation": "50,000 × 1.1 × 0.9 × 1.2 = 59,400. Adding the rates (+20%) gives 60,000, which ignores compounding.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-ci-30", "question": "A machine worth ₹1,50,000 today depreciates at 20% per annum. What will it be worth after 3 years?", "options": ["₹76,800", "₹60,000", "₹96,000", "₹81,920"], "answer": 0, "explanation": "Value = 1,50,000 × (0.8)³ = 1,50,000 × 0.512 = ₹76,800. ₹60,000 subtracts 60% simply; ₹96,000 is the value after 2 years.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-ci-31", "question": "A loan of ₹6,620 at 10% per annum compound interest is to be repaid in three equal annual instalments. What is each instalment?", "options": ["₹2,428", "₹2,200", "₹2,420", "₹2,662"], "answer": 3, "explanation": "x/1.1 + x/1.21 + x/1.331 = 6,620 → x(1.21 + 1.1 + 1)/1.331 = 6,620 → x × 3.31/1.331 = 6,620 → x = 2,000 × 1.331 = ₹2,662.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ci-32", "question": "The difference between compound interest and simple interest on a sum for 3 years at 5% per annum is ₹122. What is the sum?", "options": ["₹16,264", "₹48,800", "₹16,000", "₹15,000"], "answer": 2, "explanation": "For 3 years, CI − SI = P(3r²/100² + r³/100³) = P(0.0075 + 0.000125) = 0.007625P = 122, so P = ₹16,000. Using the 2-year formula Pr²/100² gives ₹48,800.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ci-33", "question": "A sum amounts to ₹8,820 in 2 years at 5% per annum compound interest. What simple interest would the same sum earn in 4 years at the same rate?", "options": ["₹1,764", "₹1,600", "₹1,722", "₹1,640"], "answer": 1, "explanation": "P = 8,820 ÷ 1.1025 = 8,000. SI = 8,000 × 5% × 4 = ₹1,600. ₹1,764 takes 20% of 8,820 instead of 8,000.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ci-34", "question": "₹3,903 is divided between A and B so that A's share after 7 years equals B's share after 9 years, at 4% per annum compound interest. What is A's share?", "options": ["₹2,028", "₹1,875", "₹2,000", "₹1,950"], "answer": 0, "explanation": "A(1.04)⁷ = B(1.04)⁹ → A/B = (1.04)² = 676/625. Total 1,301 parts = 3,903, so one part = 3. A = 676 × 3 = ₹2,028, B = ₹1,875 (the trap if the ratio is inverted).", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-ci-35", "question": "What will ₹6,250 amount to in 2 years at 8% per annum compound interest, compounded annually?", "options": ["₹7,200", "₹7,290", "₹7,300", "₹7,250"], "answer": 1, "explanation": "A = 6,250 × 1.08² = 6,250 × 1.1664 = ₹7,290. ₹7,250 is the simple-interest amount.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ci-36", "question": "What is the effective annual rate of interest for 10% per annum compounded half-yearly?", "options": ["10.5%", "10.25%", "10%", "20%"], "answer": 1, "explanation": "Two half-years at 5%: 1.05² = 1.1025, i.e. an effective 10.25% a year.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ci-37", "question": "What will ₹1,000 amount to in 3 years at 20% per annum compound interest, compounded annually?", "options": ["₹1,800", "₹1,680", "₹1,728", "₹1,600"], "answer": 2, "explanation": "A = 1,000 × 1.2³ = 1,000 × 1.728 = ₹1,728. ₹1,600 is the simple-interest amount.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ci-38", "question": "At 15% per annum compound interest, what is the ratio of the interest for the second year to the interest for the first year?", "options": ["1 : 1", "6 : 5", "20 : 23", "23 : 20"], "answer": 3, "explanation": "The second year's interest is earned on 1.15 times the principal, so the ratio is 1.15 : 1 = 23 : 20.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ci-39", "question": "A machine loses 10% of its value in the first year and 20% of its value in the second year. It is now worth ₹36,000. What was its original value?", "options": ["₹52,000", "₹50,000", "₹48,000", "₹51,429"], "answer": 1, "explanation": "Value now = V × 0.9 × 0.8 = 0.72V = 36,000, so V = ₹50,000. ₹51,429 treats the losses as a single 30% fall.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ci-40", "question": "The population of a village decreases by 5% every year. It is 72,200 now. What was it 2 years ago?", "options": ["80,222", "76,000", "80,000", "79,420"], "answer": 2, "explanation": "P × 0.95² = 0.9025P = 72,200, so P = 80,000. Adding 10% to 72,200 (79,420) is the slip.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ci-41", "question": "In how many years will ₹2,000 amount to ₹2,662 at 10% per annum compound interest?", "options": ["3.5 years", "2 years", "4 years", "3 years"], "answer": 3, "explanation": "2,662/2,000 = 1.331 = 1.1³, so 3 years.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ci-42", "question": "A man invests ₹10,000 at 10% per annum compound interest and withdraws ₹2,000 at the end of each year (after interest is added). What is his balance at the end of 2 years?", "options": ["₹8,100", "₹7,700", "₹8,000", "₹7,900"], "answer": 3, "explanation": "Year 1: 11,000 − 2,000 = ₹9,000. Year 2: 9,900 − 2,000 = ₹7,900.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-43", "question": "₹A invested for 2 years and ₹B invested for 3 years, both at 10% per annum compound interest, give equal amounts. What is A : B?", "options": ["11 : 10", "2 : 3", "121 : 100", "10 : 11"], "answer": 0, "explanation": "A × 1.1² = B × 1.1³, so A/B = 1.1 = 11 : 10.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ci-44", "question": "At what rate of simple interest per annum will a sum earn the same interest in 2 years as it does at 10% per annum compound interest, compounded annually?", "options": ["10.5%", "10%", "11%", "10.25%"], "answer": 0, "explanation": "CI for 2 years at 10% = 21% of the sum. SI of 21% in 2 years needs a rate of 10.5%.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-ci-45", "question": "A sum at compound interest amounts to ₹6,050 in 2 years, and the interest for the third year alone is ₹605. What is the sum?", "options": ["₹5,445", "₹5,500", "₹5,000", "₹4,840"], "answer": 2, "explanation": "Third-year interest is earned on the 2-year amount: 605/6,050 = 10%. So P × 1.21 = 6,050 and P = ₹5,000.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-46", "question": "The simple interest on a sum for 2 years is ₹960, and the compound interest on it for the same period and rate is ₹1,008. What is the sum?", "options": ["₹5,280", "₹9,600", "₹4,800", "₹4,000"], "answer": 2, "explanation": "One year's SI = ₹480. The extra ₹48 is interest on ₹480 for one year, so R = 48/480 = 10% and P = 480/0.10 = ₹4,800.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-47", "question": "A machine worth ₹1,00,000 depreciates by 10% a year for the first 2 years and by 20% a year after that. What is it worth after 4 years?", "options": ["₹50,000", "₹48,600", "₹51,840", "₹52,488"], "answer": 2, "explanation": "Value = 1,00,000 × 0.9² × 0.8² = 1,00,000 × 0.81 × 0.64 = ₹51,840. Subtracting 10 + 10 + 20 + 20 = 60% gives the simple-depreciation figure.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-48", "question": "What is the compound interest on ₹8,000 for 2 years 3 months at 10% per annum, compounded annually (simple interest for the part of a year)?", "options": ["₹1,800", "₹1,983", "₹2,000", "₹1,922"], "answer": 3, "explanation": "Amount = 8,000 × 1.1² × (1 + 0.10 × 3/12) = 9,680 × 1.025 = ₹9,922, so CI = ₹1,922.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-49", "question": "The population of a town is 62,500. Every year the birth rate is 6% and the death rate is 2% of the population at the start of that year. What will the population be after 2 years?", "options": ["67,600", "70,225", "65,000", "67,500"], "answer": 0, "explanation": "Net growth = 4% a year compounded: 62,500 × 1.04² = 62,500 × 1.0816 = 67,600. 67,500 adds 8% simply.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-ci-50", "question": "A loan taken at 10% per annum compound interest is cleared by paying ₹5,500 at the end of the first year and ₹6,050 at the end of the second year. What was the loan?", "options": ["₹11,550", "₹10,000", "₹9,500", "₹10,500"], "answer": 1, "explanation": "Present value = 5,500/1.1 + 6,050/1.21 = 5,000 + 5,000 = ₹10,000. ₹11,550 just adds the payments.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-51", "question": "At 12.5% per annum, the compound interest on a sum for 2 years exceeds the simple interest by ₹75. What is the compound interest?", "options": ["₹1,200", "₹1,350", "₹1,275", "₹1,125"], "answer": 2, "explanation": "Difference = P(1/8)² = P/64 = 75, so P = ₹4,800. CI = 4,800 × [(9/8)² − 1] = 4,800 × 17/64 = ₹1,275. ₹1,200 is the SI.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-52", "question": "The compound interest on a sum is ₹1,320 for the second year and ₹1,452 for the third year. What is the sum?", "options": ["₹12,000", "₹11,000", "₹10,000", "₹13,200"], "answer": 0, "explanation": "Rate = (1,452 − 1,320)/1,320 = 10%. Second-year interest = P × 1.1 × 0.1 = 1,320, so P = ₹12,000. ₹13,200 is the amount after the first year.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-53", "question": "How many of the following statements are correct?\n1. At the same nominal rate, half-yearly compounding gives more interest in a year than annual compounding.\n2. The difference between CI and SI for 2 years is P(r/100)².\n3. If a sum doubles in n years at compound interest, it becomes 16 times in 4n years.\n4. The compound interest for the third year alone is P(1 + r/100)³ × r/100.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 1, "explanation": "1, 2 and 3 are true (2⁴ = 16). 4 is false: the third year's interest is earned on the 2-year amount, so it is P(1 + r/100)² × r/100.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ci-54", "question": "A loan of ₹9,000 at 20% per annum compound interest is repaid in two annual instalments, the second being twice the first. What is the first instalment?", "options": ["₹3,000", "₹3,600", "₹4,500", "₹4,050"], "answer": 3, "explanation": "x/1.2 + 2x/1.44 = 9,000 gives x(5/6 + 25/18) = (40/18)x = 9,000, so x = ₹4,050. Check: 4,050/1.2 = 3,375 and 8,100/1.44 = 5,625, total ₹9,000.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-55", "question": "A sum amounts to ₹17,640 in 2 years at compound interest (compounded annually), and the simple interest on it for the same 2 years at the same rate is ₹1,600. What is the rate of interest?", "options": ["6%", "5%", "10%", "4%"], "answer": 1, "explanation": "SI per year = ₹800, so P = 800/r. Then (800/r)(1 + r)² = 17,640, i.e. r² − 20.05r + 1 = 0, giving r = 0.05 (the other root, 20, is absurd). Check: P = ₹16,000 and 16,000 × 1.05² = ₹17,640.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ci-56", "question": "₹10,000 can be invested for 3 years either at 10% per annum compound interest or at 12% per annum simple interest. Which earns more, and by how much?", "options": ["Simple interest scheme, by ₹290", "Compound interest scheme, by ₹290", "Both earn the same", "Simple interest scheme, by ₹310"], "answer": 0, "explanation": "CI = 10,000 × (1.331 − 1) = ₹3,310; SI = 10,000 × 0.36 = ₹3,600. The SI scheme earns ₹290 more; a higher simple rate can beat a lower compound rate over a short period.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-57", "question": "A car bought for ₹8,00,000 depreciates by 15% a year, while ₹5,00,000 kept in a deposit grows at 10% per annum compound interest. After 2 years, how do their values compare?", "options": ["The car is worth ₹27,000 more", "The deposit is worth ₹27,000 more", "They are worth the same", "The deposit is worth ₹55,000 more"], "answer": 1, "explanation": "Car: 8,00,000 × 0.85² = ₹5,78,000. Deposit: 5,00,000 × 1.1² = ₹6,05,000. The deposit is ₹27,000 more.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-58", "question": "What is the least number of complete years in which a sum invested at 20% per annum compound interest becomes more than double itself?", "options": ["4", "6", "3", "5"], "answer": 0, "explanation": "1.2² = 1.44, 1.2³ = 1.728 (< 2), 1.2⁴ = 2.0736 (> 2), so 4 years. Using simple interest (5 years) is the trap.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ci-59", "question": "On ₹1,60,000 at 20% per annum for 1 year, by how much does the compound interest compounded quarterly exceed that compounded half-yearly?", "options": ["₹881", "₹1,681", "₹800", "₹961"], "answer": 0, "explanation": "Quarterly: 1,60,000 × 1.05⁴ = ₹1,94,481. Half-yearly: 1,60,000 × 1.1² = ₹1,93,600. Difference = ₹881.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-60", "question": "Assertion (A): A sum that doubles in 3 years at compound interest becomes 8 times itself in 9 years.\nReason (R): Under compound interest, the amounts at equal intervals of time form a geometric progression.", "options": ["A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true", "Both A and R are true, but R is not the correct explanation of A"], "answer": 1, "explanation": "Every 3 years the amount is multiplied by 2, so in 9 years it becomes 2³ = 8 times; this is exactly the GP property in R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-ci-61", "question": "Money earns 10% per annum compound interest. Which is better: ₹12,000 now or ₹14,500 after 2 years?", "options": ["₹12,000 now, by ₹20 at the end of 2 years", "₹14,500 later, by ₹2,500", "₹14,500 later, by ₹20", "Both are equal"], "answer": 0, "explanation": "₹12,000 invested now grows to 12,000 × 1.21 = ₹14,520 in 2 years, ₹20 more than ₹14,500. Comparing ₹14,500 with ₹12,000 directly ignores the interest.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-62", "question": "A sum at compound interest amounts to ₹14,400 in 2 years and ₹20,736 in 4 years. What is the sum?", "options": ["₹9,600", "₹12,000", "₹11,000", "₹10,000"], "answer": 3, "explanation": "Over 2 years the growth factor is 20,736/14,400 = 1.44, so the rate is 20% a year. P = 14,400/1.44 = ₹10,000 (equivalently P = 14,400²/20,736).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-ci-63", "question": "A man invests ₹10,000 at 10% per annum compound interest. At the end of the first year he adds ₹5,000, and from the start of the third year the rate becomes 20%. What is his amount at the end of 3 years?", "options": ["₹19,965", "₹20,328", "₹21,780", "₹21,120"], "answer": 3, "explanation": "End of year 1: 11,000 + 5,000 = ₹16,000. Year 2 at 10%: ₹17,600. Year 3 at 20%: ₹21,120.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-ci-64", "question": "At 10% per annum, the difference between CI and SI on a sum for 3 years is ₹210 more than the difference for 2 years. What is the sum?", "options": ["₹21,000", "₹6,774", "₹10,000", "₹7,000"], "answer": 2, "explanation": "For 2 years the difference is P × 0.01; for 3 years it is P × 0.031. So 0.021P = 210 and P = ₹10,000.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id":"quant-ci-65","question":"What is the compound interest on ₹15,000 at 12% per annum for 2 years, compounded annually?","options":["₹3,600","₹3,816","₹3,960","₹18,816"],"answer":1,"explanation":"1.12² = 1.2544, so CI = 15,000 × 0.2544 = ₹3,816. ₹3,600 is the simple interest.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ci-66","question":"What will ₹20,000 amount to in 2 years at 15% per annum compound interest?","options":["₹26,450","₹26,000","₹6,450","₹26,500"],"answer":0,"explanation":"20,000 × 1.15 × 1.15 = 23,000 × 1.15 = ₹26,450.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-ci-67","question":"What will ₹50,000 amount to in 2 years at 6% per annum, compounded annually?","options":["₹56,000","₹56,360","₹6,180","₹56,180"],"answer":3,"explanation":"50,000 × 1.1236 = ₹56,180. Interest = 3,000 + 3,180 = ₹6,180.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-ci-68","question":"At what rate of compound interest per annum does ₹2,500 become ₹3,025 in 2 years?","options":["10.5%","11%","10%","21%"],"answer":2,"explanation":"3,025/2,500 = 1.21 = 1.1², so the rate is 10%. 21% is the total growth over 2 years.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ci-69","question":"A town of 40,000 people grows by 5% every year. What will its population be after 2 years?","options":["44,000","42,000","44,100","44,200"],"answer":2,"explanation":"40,000 × 1.05 × 1.05 = 42,000 × 1.05 = 44,100.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-ci-70","question":"A scooter worth ₹80,000 loses 10% of its value every year. What will it be worth after 2 years?","options":["₹64,000","₹64,800","₹65,600","₹72,000"],"answer":1,"explanation":"80,000 × 0.9 × 0.9 = ₹64,800. Subtracting 20% in one go (₹64,000) ignores that the second fall is on a lower value.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ci-71","question":"What is the compound interest on ₹40,000 at 10% per annum for 1 year, compounded half-yearly?","options":["₹4,100","₹4,000","₹4,200","₹4,050"],"answer":0,"explanation":"5% per half-year for 2 half-years: 1.05² = 1.1025, so CI = 40,000 × 0.1025 = ₹4,100.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-ci-72","question":"What is the compound interest on ₹7,500 at 4% per annum for 2 years, compounded annually?","options":["₹600","₹624","₹606","₹612"],"answer":3,"explanation":"1.04² = 1.0816, so CI = 7,500 × 0.0816 = ₹612.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-ci-73","question":"What is the effective annual rate of interest for 8% per annum compounded quarterly (to two decimal places)?","options":["8.16%","8%","8.32%","8.24%"],"answer":3,"explanation":"2% per quarter for 4 quarters: 1.02⁴ = 1.08243, an effective rate of about 8.24%.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-74","question":"On the same sum at 10% per annum for 2 years, what is the ratio of compound interest (compounded annually) to simple interest?","options":["11 : 10","20 : 21","21 : 20","1 : 1"],"answer":2,"explanation":"For ₹100: CI = ₹21 and SI = ₹20, so the ratio is 21 : 20.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-75","question":"A sum amounts to ₹19,965 in 3 years at 10% per annum compound interest. What is the sum?","options":["₹15,360","₹15,000","₹16,500","₹14,500"],"answer":1,"explanation":"1.1³ = 1.331, so the sum = 19,965 ÷ 1.331 = ₹15,000.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ci-76","question":"₹12,500 is invested at 8% per annum compound interest. What is the interest earned in the second year alone?","options":["₹1,080","₹1,000","₹2,080","₹1,160"],"answer":0,"explanation":"First-year interest = ₹1,000, so the second year starts on ₹13,500. Second-year interest = 8% of 13,500 = ₹1,080.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-77","question":"₹31,250 grows to ₹36,450 in 2 years at compound interest. What is the annual rate?","options":["8%","8.32%","16%","9%"],"answer":0,"explanation":"36,450/31,250 = 1.1664 = 1.08², so the rate is 8%. Dividing the gain evenly (8.32%) treats it as simple interest.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-78","question":"What is the compound interest on ₹24,000 at 5% per annum for 3 years, compounded annually?","options":["₹3,600","₹3,780","₹3,690","₹3,783"],"answer":3,"explanation":"1.05³ = 1.157625, so CI = 24,000 × 0.157625 = ₹3,783.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ci-79","question":"What will ₹20,000 amount to in 6 months at 8% per annum, compounded quarterly?","options":["₹20,800","₹21,632","₹20,808","₹20,816"],"answer":2,"explanation":"2% per quarter for 2 quarters: 20,000 × 1.02² = 20,000 × 1.0404 = ₹20,808.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ci-80","question":"What will ₹10,000 amount to in 1½ years at 20% per annum, compounded half-yearly?","options":["₹13,000","₹13,310","₹13,200","₹14,400"],"answer":1,"explanation":"10% per half-year for 3 half-years: 10,000 × 1.1³ = ₹13,310.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-81","question":"The compound interest on a sum is ₹500 for the first year and ₹1,025 for the first two years together. What is the rate per annum?","options":["2.5%","5%","10%","5.25%"],"answer":1,"explanation":"Second-year interest = 1,025 − 500 = ₹525. The extra ₹25 is interest on the first year's ₹500, so the rate = 25/500 = 5%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-82","question":"What is the compound interest on ₹30,000 at 7% per annum for 2 years, compounded annually?","options":["₹4,347","₹4,200","₹4,410","₹4,247"],"answer":0,"explanation":"1.07² = 1.1449, so CI = 30,000 × 0.1449 = ₹4,347.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-ci-83","question":"What sum earns ₹1,236 as compound interest in 2 years at 6% per annum, compounded annually?","options":["₹10,300","₹9,800","₹12,000","₹10,000"],"answer":3,"explanation":"Two-year CI factor at 6% = 0.1236. Sum = 1,236 ÷ 0.1236 = ₹10,000.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ci-84","question":"A motorbike bought for ₹1,00,000 loses 10% of its value every year. After how many complete years will its value first fall below ₹70,000?","options":["3","5","4","6"],"answer":2,"explanation":"Values: 90,000, 81,000, 72,900, 65,610. It first drops below ₹70,000 after 4 years, not 3 (30% ÷ 10%).","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ci-85","question":"Which deposit grows faster: 6% per annum compounded annually or 5.9% per annum compounded half-yearly?","options":["5.9% compounded half-yearly","Both grow equally","6% compounded annually","It depends on the amount"],"answer":2,"explanation":"5.9% half-yearly gives 1.0295² = 1.05987, an effective rate of about 5.99%, just below 6%. So the 6% annual deposit is slightly better.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-86","question":"A state's GDP rises from ₹4 lakh crore to ₹4.84 lakh crore in 2 years. What is its compound annual growth rate?","options":["10.5%","10%","21%","11%"],"answer":1,"explanation":"4.84/4 = 1.21 = 1.1², so the CAGR is 10%. 10.5% simply halves the 21% total rise.","difficulty":"moderate","source":"IBPS PO · RBI Assistant"},
  {"id":"quant-ci-87","question":"A flat bought for ₹50 lakh appreciates by 8% every year. What is its approximate value after 3 years?","options":["₹62.99 lakh","₹62 lakh","₹63.5 lakh","₹62.5 lakh"],"answer":0,"explanation":"50 × 1.08³ = 50 × 1.259712 ≈ ₹62.99 lakh. Adding 24% (₹62 lakh) treats it as simple growth.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ci-88","question":"A sum doubles in 5 years at compound interest and amounts to ₹64,000 after 15 years. What is the sum?","options":["₹16,000","₹21,333","₹4,000","₹8,000"],"answer":3,"explanation":"15 years = 3 doubling periods, so the sum is multiplied by 2³ = 8. Sum = 64,000 ÷ 8 = ₹8,000.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-89","question":"Ravi puts ₹50,000 in a deposit at 8% compound interest, and Sita puts ₹54,000 in a deposit at 8% simple interest. After 2 years, how much more does Sita have than Ravi?","options":["₹4,000","₹3,680","₹4,640","₹4,320"],"answer":3,"explanation":"Ravi: 50,000 × 1.1664 = ₹58,320. Sita: 54,000 × 1.16 = ₹62,640. Difference = ₹4,320.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-ci-90","question":"A sum becomes 1.21 times itself in one year at compound interest, compounded half-yearly. What is the annual rate?","options":["21%","10%","20%","10.5%"],"answer":2,"explanation":"1.21 = 1.1², so the half-yearly rate is 10% and the annual rate is 20%. 21% is the effective, not the nominal, rate.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-91","question":"A plot bought for ₹25 lakh gains 20% in value every year. What is it worth after 3 years?","options":["₹40 lakh","₹43.2 lakh","₹42 lakh","₹45 lakh"],"answer":1,"explanation":"25 × 1.2³ = 25 × 1.728 = ₹43.2 lakh. Simple growth of 60% gives only ₹40 lakh.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-92","question":"The compound interest on ₹12,000 for 2 years at r% per annum, compounded annually, is ₹2,520. What is r?","options":["10","10.5","21","11"],"answer":0,"explanation":"Amount = ₹14,520 and 14,520/12,000 = 1.21 = 1.1². So r = 10.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-ci-93","question":"On ₹40,000 at 10% per annum for 2 years, by how much does the compound interest compounded half-yearly exceed the compound interest compounded annually?","options":["₹220.25","₹200","₹410","₹110.13"],"answer":0,"explanation":"Half-yearly: 1.05⁴ = 1.21550625; annually: 1.1² = 1.21. Difference = 40,000 × 0.00550625 = ₹220.25.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-94","question":"A person deposits ₹10,000 at the start of each year for 3 years in a scheme paying 10% compound interest. What is the balance at the end of the third year?","options":["₹33,100","₹36,000","₹34,410","₹36,410"],"answer":3,"explanation":"The deposits grow for 3, 2 and 1 years: 13,310 + 12,100 + 11,000 = ₹36,410.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-95","question":"A town of 40,000 grows by 5% a year, but 1,000 people move away at the end of each year. What will the population be after 2 years?","options":["42,100","41,000","42,050","44,100"],"answer":2,"explanation":"Year 1: 42,000 − 1,000 = 41,000. Year 2: 41,000 × 1.05 − 1,000 = 43,050 − 1,000 = 42,050.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-ci-96","question":"At 10% per annum compound interest, the interest for the third year on a sum exceeds the interest for the second year by ₹132. What is the sum?","options":["₹13,200","₹12,000","₹11,000","₹10,000"],"answer":1,"explanation":"Second-year interest = 0.11P and third-year interest = 0.121P. The difference 0.011P = ₹132, so P = ₹12,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-97","question":"At what annual rate, compounded half-yearly, will ₹5,000 amount to ₹6,655 in 1½ years?","options":["10%","20%","22%","21%"],"answer":1,"explanation":"6,655/5,000 = 1.331 = 1.1³ over three half-years. So the half-yearly rate is 10% and the annual rate 20%.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-98","question":"Bank A offers 10% per annum compounded annually and Bank B offers 9.5% per annum compounded half-yearly. On ₹1,00,000 for 2 years, which bank pays more and by about how much?","options":["Bank B, by ₹602.87","Bank A, by ₹500","Bank A, by ₹602.87","Both pay the same"],"answer":2,"explanation":"Bank A: 1.1² = 1.21 → ₹1,21,000. Bank B: 1.0475⁴ ≈ 1.20397 → ₹1,20,397.13. Bank A pays about ₹602.87 more; half-yearly compounding does not make up for a 0.5% lower rate.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-99","question":"At what annual rate is the difference between compound interest and simple interest on a sum for 2 years exactly 1% of the sum?","options":["1%","10%","5%","20%"],"answer":1,"explanation":"For 2 years, CI − SI = P × (r/100)². Setting this equal to P/100 gives (r/100)² = 0.01, so r = 10%.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-100","question":"A sum doubles in 3 years at compound interest. The annual rate is closest to:","options":["26%","33.33%","30%","23%"],"answer":0,"explanation":"(1 + r)³ = 2 gives 1 + r = ∛2 ≈ 1.26, so r ≈ 26%. 33.33% is the simple-interest rate that doubles money in 3 years.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-ci-101","question":"The simple interest on a sum for 3 years at 10% per annum is ₹4,500. What is the compound interest on half that sum for 2 years at 20% per annum, compounded annually?","options":["₹6,600","₹3,000","₹3,600","₹3,300"],"answer":3,"explanation":"The sum = 4,500/0.3 = ₹15,000, so half = ₹7,500. CI at 20% for 2 years = 44%: 7,500 × 0.44 = ₹3,300.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-102","question":"A village's population grows by 4% a year at compound rate. In 2 years it increased by 2,040. What was the population at the start?","options":["25,500","26,010","24,000","25,000"],"answer":3,"explanation":"Two-year growth = 1.04² − 1 = 8.16%. Population = 2,040 ÷ 0.0816 = 25,000. Using 8% gives 25,500.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-ci-103","question":"What is the compound interest on ₹25,000 for 3 years if the rates for the three years are 4%, 5% and 6% respectively?","options":["₹3,750","₹3,900","₹3,938","₹3,983"],"answer":2,"explanation":"Amount = 25,000 × 1.04 × 1.05 × 1.06 = 25,000 × 1.15752 = ₹28,938. CI = ₹3,938.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-104","question":"At 10% per annum, the compound interest on a sum for 2 years exceeds the compound interest on it for 1 year by ₹2,200. What is the sum?","options":["₹22,000","₹20,000","₹11,000","₹10,000"],"answer":1,"explanation":"2-year CI = 21% and 1-year CI = 10%, so the difference is 11% of the sum = ₹2,200. Sum = ₹20,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-105","question":"On ₹20,000 at 10% per annum for 1 year, by how much does the compound interest compounded half-yearly exceed the simple interest?","options":["₹50","₹100","₹25","₹205"],"answer":0,"explanation":"Half-yearly: 20,000 × (1.05² − 1) = ₹2,050. SI = ₹2,000. The extra ₹50 is 5% interest on the first half-year's ₹1,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ci-106","question":"A bacterial culture grows by 50% every hour. Starting from 6,400 cells, after how many complete hours will it first exceed 30,000 cells?","options":["4","3","5","8"],"answer":0,"explanation":"6,400 → 9,600 → 14,400 → 21,600 → 32,400. It first exceeds 30,000 after 4 hours.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-ci-107","question":"A man borrows ₹10,000 at 10% per annum simple interest and lends the whole amount at 10% per annum compound interest, compounded half-yearly. What does he gain in 2 years?","options":["₹100","₹210","₹55.06","₹155.06"],"answer":3,"explanation":"He earns 10,000 × (1.05⁴ − 1) = ₹2,155.06 and pays ₹2,000 simple interest. Gain = ₹155.06.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-108","question":"At compound interest a sum becomes 1.5 times itself in 4 years. What will it become in 12 years?","options":["4.5 times","3 times","3.375 times","2.25 times"],"answer":2,"explanation":"12 years = three 4-year periods, so the factor is 1.5³ = 3.375. Multiplying 1.5 by 3 treats the growth as simple.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-109","question":"A car bought for ₹6 lakh loses 20% of its value each year. The owner sells it after 2 years and invests the money at 10% per annum compound interest for 2 years. What is the final amount?","options":["₹4,80,000","₹4,64,640","₹4,35,600","₹4,60,800"],"answer":1,"explanation":"Sale value = 6,00,000 × 0.64 = ₹3,84,000. After 2 years at 10%: 3,84,000 × 1.21 = ₹4,64,640.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-110","question":"A mutual fund loses 20% in its first year and gains 25% in its second year. What is its compound annual growth rate over the two years?","options":["2.5%","0%","5%","−2.5%"],"answer":1,"explanation":"0.8 × 1.25 = 1, so the investment is back where it started: the CAGR is 0%. Averaging −20% and +25% (2.5%) is the trap.","difficulty":"hard","source":"IBPS PO · RBI Assistant"},
  {"id":"quant-ci-111","question":"A town's population rises by 10% in every odd-numbered year and falls by 10% in every even-numbered year. If it is 1,00,000 at the start of year 1, what is it at the end of year 4?","options":["98,010","1,00,000","99,000","96,060"],"answer":0,"explanation":"Each pair of years multiplies by 1.1 × 0.9 = 0.99. After 2 pairs: 1,00,000 × 0.99² = 98,010.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-112","question":"A machine depreciates at a fixed rate every year, and after 2 years its value is 64% of the original. If it was bought for ₹5 lakh, what will it be worth after 3 years?","options":["₹2,40,000","₹2,80,000","₹3,20,000","₹2,56,000"],"answer":3,"explanation":"0.64 = 0.8², so it keeps 80% each year (20% depreciation). After 3 years: 5,00,000 × 0.8³ = 5,00,000 × 0.512 = ₹2,56,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-113","question":"₹1 lakh is invested at 10% compound interest for 2 years, and the whole amount is then invested at 12% simple interest for 3 years. What is the final amount?","options":["₹1,58,000","₹1,70,000","₹1,64,560","₹1,66,000"],"answer":2,"explanation":"After 2 years: ₹1,21,000. Simple interest at 12% for 3 years adds 36%: 1,21,000 × 1.36 = ₹1,64,560.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-ci-114","question":"A man borrows ₹80,000 at 8% per annum compound interest. He repays ₹43,312 at the end of 2 years. How much must he pay at the end of the third year to clear the loan?","options":["₹50,000","₹53,312","₹54,000","₹55,600"],"answer":2,"explanation":"Due after 2 years = 80,000 × 1.1664 = ₹93,312. After paying 43,312, ₹50,000 remains, which grows to ₹54,000 in a year.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-115","question":"What is the compound interest on ₹15,625 for 9 months at 16% per annum, compounded quarterly?","options":["₹1,875","₹1,951","₹2,000","₹1,976"],"answer":1,"explanation":"4% per quarter for 3 quarters: 15,625 × 1.04³ = 15,625 × 1.124864 = ₹17,576. CI = ₹1,951. ₹1,875 is the simple interest.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-116","question":"On ₹50,000 for 2 years, which earns more: 10% per annum compound interest (compounded annually) or 10.5% per annum simple interest?","options":["Both earn the same","Compound interest, by ₹250","Simple interest, by ₹250","Compound interest, by ₹500"],"answer":0,"explanation":"CI for 2 years at 10% = 21% of the sum; SI at 10.5% for 2 years = 21% too. Both earn ₹10,500.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-117","question":"A sum amounts to ₹11,664 in 2 years at compound interest (compounded annually), and the simple interest on it for the same 2 years at the same rate is ₹1,600. What is the sum?","options":["₹9,600","₹10,800","₹8,000","₹10,000"],"answer":3,"explanation":"Yearly SI = ₹800 = Pr. Amount = P + 2Pr + Pr² = P + 1,600 + 800r = 11,664. Trying r = 8%: P = 10,000 and 10,000 + 64 = 10,064 ✓. Sum = ₹10,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-ci-118","question":"At compound interest, the interest on a sum is ₹1,100 for the second year and ₹1,331 for the fourth year. What is the sum?","options":["₹11,000","₹12,100","₹10,000","₹9,091"],"answer":2,"explanation":"Interest grows by (1 + r)² from year 2 to year 4: 1,331/1,100 = 1.21, so r = 10%. Second-year interest = P × 0.1 × 1.1 = 0.11P = 1,100, giving P = ₹10,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-119","question":"Money can earn 10% per annum compound interest. Which is worth more today: ₹10,000 now, or ₹6,050 after 1 year plus ₹6,050 after 2 years — and by how much in today's money?","options":["₹10,000 now, by ₹500","The two payments, by ₹500","The two payments, by ₹2,100","Both are worth the same"],"answer":1,"explanation":"Present value = 6,050/1.1 + 6,050/1.21 = 5,500 + 5,000 = ₹10,500, which beats ₹10,000 by ₹500.","difficulty":"very-hard","source":"IBPS PO · RBI Grade B"},
  {"id":"quant-ci-120","question":"The compound interest on a sum for 3 years at 10% per annum equals the simple interest on it for 3 years at r% per annum. What is r (to two decimal places)?","options":["10","11.03","11","10.33"],"answer":1,"explanation":"CI for 3 years at 10% = 33.1% of the sum. SI at r% for 3 years = 3r%. So r = 33.1/3 ≈ 11.03.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ci-121","question":"₹50,000 is split into two parts: X at 10% compound interest for 2 years and Y at 12% simple interest for 2 years. The total interest is ₹11,250. What is Y?","options":["₹25,000","₹20,000","₹30,000","₹27,500"],"answer":0,"explanation":"Rates for 2 years: 21% on X and 24% on Y. If all were at 21%, interest = ₹10,500; the extra ₹750 is 3% of Y, so Y = ₹25,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-122","question":"For how long must a sum be lent at 10% simple interest to earn the same interest that it earns in 2 years at 10% compound interest, compounded annually?","options":["2 years","2.5 years","2.2 years","2.1 years"],"answer":3,"explanation":"CI for 2 years = 21% of the sum. At 10% simple interest, 21% takes 2.1 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-123","question":"A deposit earns 8% per annum compound interest while prices rise by 5% every year. By roughly what percent does its real purchasing power grow in 2 years?","options":["6%","3%","5.8%","6.1%"],"answer":2,"explanation":"Real growth factor per year = 1.08/1.05 ≈ 1.02857. Over 2 years: 1.02857² ≈ 1.058, about 5.8%. Subtracting rates (3% a year → 6%) is only an approximation.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO Mains"},
  {"id":"quant-ci-124","question":"₹1 lakh is invested at 12% compound interest, but 30% tax is paid each year out of that year's interest, and only the rest is reinvested. What is the value after 2 years?","options":["₹1,17,808","₹1,25,440","₹1,17,505.60","₹1,16,800"],"answer":2,"explanation":"Post-tax rate = 12 × 0.7 = 8.4%. Value = 1,00,000 × 1.084² = ₹1,17,505.60. Taxing 30% of the total 2-year interest at the end (₹1,17,808) ignores that tax leaves the fund every year.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-ci-125","question":"A person deposits ₹X at the end of each year for 3 years in a scheme paying 10% compound interest, and has ₹33,100 just after the third deposit. What is X?","options":["₹11,000","₹10,000","₹9,000","₹10,030"],"answer":1,"explanation":"The deposits grow for 2, 1 and 0 years: X(1.21 + 1.1 + 1) = 3.31X = 33,100, so X = ₹10,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-ci-126","question":"The compound interest on ₹A for 2 years at 10% per annum (compounded annually) equals the simple interest on ₹B for 3 years at 7% per annum. What is A : B?","options":["1 : 1","10 : 7","3 : 2","7 : 10"],"answer":0,"explanation":"CI rate for 2 years at 10% = 21%; SI for 3 years at 7% = 21%. So 0.21A = 0.21B and A : B = 1 : 1.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-127","question":"On a sum at 20% per annum for 2 years, compound interest compounded half-yearly exceeds compound interest compounded annually by ₹482. What is the sum?","options":["₹24,100","₹48,200","₹10,000","₹20,000"],"answer":3,"explanation":"Half-yearly: 1.1⁴ = 1.4641; annually: 1.2² = 1.44. Difference = 0.0241 of the sum = ₹482, so the sum = ₹20,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-128","question":"A sum becomes 1.69 times itself in 2 years at compound interest. The simple interest on the same sum at the same rate for 5 years is ₹6,000. What is the sum?","options":["₹3,550","₹6,000","₹3,000","₹4,000"],"answer":3,"explanation":"1.69 = 1.3², so the rate is 30%. SI for 5 years = 150% of the sum = ₹6,000, so the sum = ₹4,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-ci-129","question":"The compound interest on a sum for the first year is ₹800, and for the first three years together it is ₹2,648 (compounded annually). What is the sum?","options":["₹8,800","₹10,000","₹8,000","₹6,620"],"answer":2,"explanation":"CI(3 years)/CI(1 year) = 3 + 3r + r² = 2,648/800 = 3.31, which gives r = 0.1. Since Pr = 800, the sum = ₹8,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-130","question":"₹10,000 is invested at 10% compound interest and ₹11,000 at 10% simple interest on the same day. After how many complete years does the compound-interest amount first exceed the simple-interest amount?","options":["5","6","7","10"],"answer":1,"explanation":"Compare 10,000 × 1.1ⁿ with 11,000 + 1,100n: at n = 5, 16,105 < 16,500; at n = 6, 17,715.61 > 17,600. So 6 years.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-ci-131","question":"At compound interest (compounded annually), the interest for the second year is 8% more than the interest for the first year. What is the rate of interest?","options":["8%","4%","16%","10%"],"answer":0,"explanation":"Second-year interest = first-year interest × (1 + r), because it is earned on the first year's amount. So 1 + r = 1.08 and r = 8%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-132","question":"A fund grows by 12% in year 1, grows by 25% in year 2 and falls by 20% in year 3. What is its approximate compound annual growth rate over the three years?","options":["3.85%","5.67%","4%","12%"],"answer":0,"explanation":"Overall factor = 1.12 × 1.25 × 0.8 = 1.12. CAGR = ∛1.12 − 1 ≈ 3.85%. The average of the three returns (5.67%) overstates it.","difficulty":"very-hard","source":"IBPS PO Mains · RBI Grade B"},
  {"id":"quant-ci-133","question":"The compound interest on a sum for the first 2 years is ₹2,100, and for the first 3 years it is ₹3,310 (compounded annually). What is the rate of interest?","options":["11.5%","5%","12.1%","10%"],"answer":3,"explanation":"Third-year interest = 3,310 − 2,100 = ₹1,210, and it equals the 2-year amount × r. Trying 10%: the sum is 2,100/0.21 = ₹10,000, the 2-year amount ₹12,100, and 10% of it is ₹1,210 ✓.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-134","question":"The compound interest on a sum for 2 years is ₹832 and the simple interest for the same period at the same rate is ₹800. What is the compound interest on the sum for 3 years?","options":["₹1,200","₹1,280","₹1,298.56","₹1,248"],"answer":2,"explanation":"CI − SI = ₹32 = interest on one year's interest (₹400), so r = 8%. Sum = 400/0.08 = ₹5,000. 3-year CI = 5,000 × (1.08³ − 1) = 5,000 × 0.259712 = ₹1,298.56.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO"},
  {"id":"quant-ci-135","question":"A sum earns compound interest at 10% in the first year and 20% in the second year. What single annual rate, compounded annually for 2 years, gives the same amount?","options":["15%","14.89%","15.5%","14.5%"],"answer":1,"explanation":"Factor = 1.1 × 1.2 = 1.32. Equivalent rate = √1.32 − 1 ≈ 14.89%, a little below the plain average of 15%.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-ci-136","question":"What is the compound interest on ₹64,000 for 1 year at 15% per annum, compounded half-yearly?","options":["₹9,960","₹9,600","₹10,080","₹9,840"],"answer":0,"explanation":"7.5% per half-year: 1.075² = 1.155625. CI = 64,000 × 0.155625 = ₹9,960.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-ci-137","question":"The compound interest on a sum for 2 years at 20% per annum exceeds the compound interest on it for 2 years at 10% per annum by ₹2,300. What is the sum?","options":["₹11,500","₹23,000","₹12,000","₹10,000"],"answer":3,"explanation":"2-year CI rates: 44% at 20% and 21% at 10%. The 23% difference = ₹2,300, so the sum = ₹10,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-ci-138","question":"At 25% per annum compound interest, the interest for the third year on a sum is ₹3,125. What is the sum?","options":["₹12,500","₹10,000","₹8,000","₹6,400"],"answer":2,"explanation":"Third-year interest = P × 1.25² × 0.25 = 0.390625P = 3,125, so P = ₹8,000.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-ci-139","question":"In how many years will ₹1,331 amount to ₹1,771.561 at 10% per annum compound interest?","options":["4 years","3 years","2 years","5 years"],"answer":1,"explanation":"1,771.561/1,331 = 1.331 = 1.1³, so 3 years.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
];

export default questions;
